def match(orders):
    trades = []
    # Buy book: list of (price, arrival_time, id, qty_remaining)
    # Sell book: list of (price, arrival_time, id, qty_remaining)
    buy_book = []
    sell_book = []
    arrival_time = 0
    order_map = {}  # id -> (side, index in book)

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, book_idx = order_map[order_id]
                if side == 'buy':
                    if book_idx < len(buy_book) and buy_book[book_idx][2] == order_id:
                        buy_book[book_idx] = (buy_book[book_idx][0], buy_book[book_idx][1], buy_book[book_idx][2], 0)
                else:
                    if book_idx < len(sell_book) and sell_book[book_idx][2] == order_id:
                        sell_book[book_idx] = (sell_book[book_idx][0], sell_book[book_idx][1], sell_book[book_idx][2], 0)
                del order_map[order_id]

        elif order[0] == 'market':
            order_id = order[1]
            side = order[2]
            qty = order[3]

            if side == 'buy':
                # Match against sell_book, lowest price first
                sell_book.sort(key=lambda x: (x[0], x[1]))
                for i, (price, arr_time, sell_id, sell_qty) in enumerate(sell_book):
                    if sell_qty <= 0:
                        continue
                    if qty <= 0:
                        break
                    trade_qty = min(qty, sell_qty)
                    trades.append([order_id, sell_id, price, trade_qty])
                    qty -= trade_qty
                    sell_book[i] = (price, arr_time, sell_id, sell_qty - trade_qty)
